const fs = require('node:fs');
const path = require('node:path');
// Apply the project's own checked-in patches to its installed dependencies.
// The consuming project invokes this from a package script; patchkit itself
// declares no install hook.
for (const patch of fs.readdirSync('patches')) {
  const target = path.join('node_modules', patch.replace(/\.patch$/, ''));
  fs.writeFileSync(path.join(target, '.patchkit-applied'), 'ok');
}

